pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(0x1234);
        address receiver = address(0x5678);
        uint amount = 1 ether;

        // Fund the contract with some ether
        vm.deal(address(c), 10 ether);

        // Record balance before non-owner call
        uint balanceBefore = address(c).balance;

        // Non-owner attempts to call sendTo
        vm.prank(nonOwner);
        c.sendTo(receiver, amount);

        // Check balance after: buggy version will have sent ether, reference would have reverted
        uint balanceAfter = address(c).balance;
        assertTrue(balanceAfter < balanceBefore);
    }
}

